-- Canonical tenant references use composite keys, independent of browser input.
CREATE TABLE malls (id uuid PRIMARY KEY, name text NOT NULL CHECK(length(name) BETWEEN 1 AND 120), planning_capacity integer NOT NULL DEFAULT 1500 CHECK(planning_capacity > 0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE merchants (id uuid PRIMARY KEY, name text NOT NULL CHECK(length(name) BETWEEN 1 AND 120), version integer NOT NULL DEFAULT 1 CHECK(version > 0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships (merchant_id uuid NOT NULL REFERENCES merchants(id), user_id text NOT NULL REFERENCES "user"(id), role text NOT NULL CHECK(role IN ('owner','staff')), permissions text[] NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','revoked')), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(merchant_id,user_id), CHECK(permissions <@ ARRAY['catalogue','design','publish','finance','sensitive']::text[]));
CREATE INDEX memberships_user ON memberships(user_id,status);
CREATE TABLE operator_grants (user_id text NOT NULL REFERENCES "user"(id), permission text NOT NULL CHECK(permission IN ('support','review','finance','moderation','recovery','jobs')), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,permission));
CREATE TABLE applications (id uuid PRIMARY KEY, merchant_id uuid NOT NULL REFERENCES merchants(id), applicant_id text NOT NULL REFERENCES "user"(id), state text NOT NULL CHECK(state IN ('draft','submitted','reviewing','needs_information','approved','rejected')), version integer NOT NULL DEFAULT 1 CHECK(version > 0), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,merchant_id));
CREATE TABLE shops (id uuid PRIMARY KEY, merchant_id uuid NOT NULL REFERENCES merchants(id), mall_id uuid NOT NULL REFERENCES malls(id), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 120), slug text NOT NULL UNIQUE CHECK(slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND length(slug)<=80), version integer NOT NULL DEFAULT 1 CHECK(version > 0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,merchant_id));
CREATE INDEX shops_merchant ON shops(merchant_id,id);
CREATE TABLE shop_publication (shop_id uuid PRIMARY KEY REFERENCES shops(id), state text NOT NULL CHECK(state IN ('provisioning','unpublished','active','temporarily_closed','archived')), version integer NOT NULL DEFAULT 1 CHECK(version > 0));
CREATE TABLE tenancies (shop_id uuid PRIMARY KEY REFERENCES shops(id), state text NOT NULL CHECK(state IN ('pending','active','due','grace','closed')), period_start timestamptz, period_end timestamptz, version integer NOT NULL DEFAULT 1 CHECK(version > 0), CHECK((period_start IS NULL AND period_end IS NULL) OR (period_start IS NOT NULL AND period_end IS NOT NULL AND period_end > period_start)));
CREATE TABLE shop_moderation (shop_id uuid PRIMARY KEY REFERENCES shops(id), state text NOT NULL CHECK(state IN ('clear','under_review','suspended')), version integer NOT NULL DEFAULT 1 CHECK(version > 0));
CREATE TABLE departments (id uuid PRIMARY KEY, shop_id uuid NOT NULL, merchant_id uuid NOT NULL, name text NOT NULL CHECK(length(name) BETWEEN 1 AND 120), slug text NOT NULL, position integer NOT NULL CHECK(position>=0), FOREIGN KEY(shop_id,merchant_id) REFERENCES shops(id,merchant_id), UNIQUE(id,shop_id,merchant_id), UNIQUE(shop_id,slug));
CREATE TABLE products (id uuid PRIMARY KEY, shop_id uuid NOT NULL, merchant_id uuid NOT NULL, department_id uuid NOT NULL, kind text NOT NULL CHECK(kind IN ('product','service')), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 160), slug text NOT NULL, currency text NOT NULL CHECK(currency IN ('UGX','USD','KES','EUR','GBP')), price_minor numeric(20,0) CHECK(price_minor>=0), availability text NOT NULL CHECK(availability IN ('available','unavailable','archived')), version integer NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(shop_id,merchant_id) REFERENCES shops(id,merchant_id), FOREIGN KEY(department_id,shop_id,merchant_id) REFERENCES departments(id,shop_id,merchant_id), UNIQUE(id,shop_id,merchant_id), UNIQUE(shop_id,slug));
CREATE INDEX products_shop ON products(shop_id,availability,id);
CREATE TABLE media_assets (id uuid PRIMARY KEY, shop_id uuid NOT NULL, merchant_id uuid NOT NULL, state text NOT NULL CHECK(state IN ('uploaded','validating','processing','ready','rejected','failed')), storage_key text NOT NULL UNIQUE, version integer NOT NULL DEFAULT 1 CHECK(version>0), FOREIGN KEY(shop_id,merchant_id) REFERENCES shops(id,merchant_id), UNIQUE(id,shop_id,merchant_id));
CREATE TABLE shop_revisions (id uuid PRIMARY KEY, shop_id uuid NOT NULL, merchant_id uuid NOT NULL, revision integer NOT NULL CHECK(revision>0), schema_version integer NOT NULL CHECK(schema_version>0), design jsonb NOT NULL CHECK(jsonb_typeof(design)='object'), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(shop_id,merchant_id) REFERENCES shops(id,merchant_id), UNIQUE(shop_id,revision), UNIQUE(id,shop_id,merchant_id));
CREATE TABLE invoices (id uuid PRIMARY KEY, merchant_id uuid NOT NULL REFERENCES merchants(id), application_id uuid, shop_id uuid, currency text NOT NULL CHECK(currency IN ('UGX','USD','KES','EUR','GBP')), amount_minor numeric(20,0) NOT NULL CHECK(amount_minor>0), period_start timestamptz NOT NULL, period_end timestamptz NOT NULL CHECK(period_end>period_start), created_at timestamptz NOT NULL DEFAULT now(), CHECK(application_id IS NOT NULL OR shop_id IS NOT NULL), FOREIGN KEY(application_id,merchant_id) REFERENCES applications(id,merchant_id), FOREIGN KEY(shop_id,merchant_id) REFERENCES shops(id,merchant_id), UNIQUE(id,merchant_id,currency));
CREATE TABLE rent_events (id uuid PRIMARY KEY, invoice_id uuid NOT NULL, merchant_id uuid NOT NULL, currency text NOT NULL, amount_minor numeric(20,0) NOT NULL CHECK(amount_minor<>0), kind text NOT NULL CHECK(kind IN ('charge','payment','waiver','adjustment')), source text NOT NULL, source_reference text NOT NULL, actor_id text NOT NULL REFERENCES "user"(id), reason text NOT NULL CHECK(length(reason) BETWEEN 1 AND 500), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(invoice_id,merchant_id,currency) REFERENCES invoices(id,merchant_id,currency), UNIQUE(source,source_reference));
CREATE TABLE invitations (id uuid PRIMARY KEY, merchant_id uuid NOT NULL REFERENCES merchants(id), email text NOT NULL, token_hash text NOT NULL UNIQUE, role text NOT NULL CHECK(role IN ('owner','staff')), permissions text[] NOT NULL DEFAULT '{}', expires_at timestamptz NOT NULL, accepted_at timestamptz, revoked_at timestamptz, invited_by text NOT NULL REFERENCES "user"(id), created_at timestamptz NOT NULL DEFAULT now(), CHECK(permissions <@ ARRAY['catalogue','design','publish','finance','sensitive']::text[]));
CREATE TABLE mfa_proofs (session_id text PRIMARY KEY REFERENCES session(id) ON DELETE CASCADE, user_id text NOT NULL REFERENCES "user"(id), verified_at timestamptz NOT NULL, method text NOT NULL CHECK(method IN ('totp','backup')));
CREATE TABLE audit_events (id uuid PRIMARY KEY, merchant_id uuid REFERENCES merchants(id), actor_id text REFERENCES "user"(id), action text NOT NULL, resource_id text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_merchant ON audit_events(merchant_id,created_at,id);
CREATE FUNCTION prevent_history_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'History is append-only'; END $$;
CREATE TRIGGER audit_append_only BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION prevent_history_mutation();
CREATE TRIGGER rent_append_only BEFORE UPDATE OR DELETE ON rent_events FOR EACH ROW EXECUTE FUNCTION prevent_history_mutation();
CREATE TRIGGER revision_append_only BEFORE UPDATE OR DELETE ON shop_revisions FOR EACH ROW EXECUTE FUNCTION prevent_history_mutation();
CREATE FUNCTION prevent_shop_identity_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.id <> OLD.id OR NEW.merchant_id <> OLD.merchant_id THEN RAISE EXCEPTION 'Shop identity is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER shop_identity BEFORE UPDATE ON shops FOR EACH ROW EXECUTE FUNCTION prevent_shop_identity_change();
